#!/usr/bin/env node
/**
 * Generates nodes/Brevo/operations.generated.ts from the official Brevo Node SDK
 * (https://github.com/getbrevo/brevo-node), which is itself generated by Fern from
 * Brevo's OpenAPI definition (https://api.brevo.com/v3/swagger_definition_v3.yml).
 *
 * Every resource client is parsed with the TypeScript compiler API so that every
 * endpoint (method, path, path/query/body/multipart params, types, enums, docs) is
 * extracted automatically. Re-run after updating the SDK checkout:
 *
 *   node scripts/generate-operations.js /path/to/brevo-node
 */
'use strict';

const fs = require('fs');
const path = require('path');
let ts;
try {
	ts = require('typescript');
} catch {
	ts = require(path.join(require('child_process').execSync('npm root -g').toString().trim(), 'typescript'));
}

const sdkRoot = path.resolve(process.argv[2] || '../brevo-node');
const outFile = path.resolve(__dirname, '../nodes/Brevo/operations.generated.ts');
const resourcesDir = path.join(sdkRoot, 'src/api/resources');
const sdkVersion = JSON.parse(fs.readFileSync(path.join(sdkRoot, 'package.json'), 'utf8')).version;

const RESOURCE_NAMES = {
	account: 'Account',
	balance: 'Balance (Loyalty)',
	companies: 'Company (CRM)',
	consentGroups: 'Consent Group',
	contacts: 'Contact',
	conversations: 'Conversation',
	coupons: 'Coupon',
	customObjects: 'Custom Object',
	deals: 'Deal (CRM)',
	domains: 'Domain',
	ecommerce: 'E-Commerce',
	emailCampaigns: 'Email Campaign',
	event: 'Event',
	externalFeeds: 'External Feed',
	files: 'File (CRM)',
	inboundParsing: 'Inbound Parsing',
	masterAccount: 'Master Account',
	notes: 'Note (CRM)',
	oAuth: 'OAuth',
	payments: 'Payment',
	process: 'Process',
	program: 'Program (Loyalty)',
	reward: 'Reward (Loyalty)',
	senders: 'Sender',
	smsCampaigns: 'SMS Campaign',
	smsTemplates: 'SMS Template',
	tasks: 'Task (CRM)',
	tier: 'Tier (Loyalty)',
	transactionalEmails: 'Transactional Email',
	transactionalSms: 'Transactional SMS',
	transactionalWhatsApp: 'Transactional WhatsApp',
	user: 'User',
	wallet: 'Wallet (Loyalty)',
	webhooks: 'Webhook',
	whatsAppCampaigns: 'WhatsApp Campaign',
};

const ACRONYMS = { sms: 'SMS', smtp: 'SMTP', crm: 'CRM', id: 'ID', ids: 'IDs', url: 'URL', doi: 'DOI', ip: 'IP', ips: 'IPs', o: 'O', m2m: 'M2M', b2b: 'B2B', api: 'API', mfa: 'MFA', sso: 'SSO' };

function humanize(name) {
	const words = name
		.replace(/^_+/, '')
		.replace(/([a-z0-9])([A-Z])/g, '$1 $2')
		.replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
		.replace(/[_-]+/g, ' ')
		.split(/\s+/)
		.filter(Boolean);
	return words
		.map((w) => {
			const l = w.toLowerCase();
			if (ACRONYMS[l]) return ACRONYMS[l];
			if (l === 'whatsapp') return 'WhatsApp';
			if (l === 'oauth') return 'OAuth';
			return l.charAt(0).toUpperCase() + l.slice(1);
		})
		.join(' ')
		.replace(/\bWhats App\b/g, 'WhatsApp')
		.replace(/\bO Auth\b/g, 'OAuth')
		.replace(/\bM2 M\b/g, 'M2M')
		.replace(/\bAb Test\b/g, 'A/B Test')
		.replace(/\bTransac\b/g, 'Transactional')
		.replace(/\bUpdation\b/g, 'Update');
}

function cleanDoc(text) {
	if (!text) return '';
	return text
		.replace(/<br\s*\/?>/gi, ' ')
		.replace(/<\/?[a-zA-Z][^>]*>/g, '')
		.replace(/''/g, "'")
		.replace(/\s+/g, ' ')
		.trim();
}

function firstSentence(text, max = 220) {
	const t = cleanDoc(text);
	const m = t.match(/^(.+?[.!?])(\s|$)/);
	let s = m ? m[1] : t;
	if (s.length > max) s = s.slice(0, max - 1).trimEnd() + '…';
	return s;
}

// ---------------------------------------------------------------- program
const clientFiles = fs
	.readdirSync(resourcesDir)
	.filter((d) => fs.existsSync(path.join(resourcesDir, d, 'client/Client.ts')))
	.sort();

const program = ts.createProgram(
	clientFiles.map((d) => path.join(resourcesDir, d, 'client/Client.ts')),
	{ target: ts.ScriptTarget.ES2020, module: ts.ModuleKind.CommonJS, strict: true, skipLibCheck: true, noEmit: true },
);
const checker = program.getTypeChecker();

// ---------------------------------------------------------------- type description
function stripNullish(type) {
	if (type.isUnion()) {
		const parts = type.types.filter((t) => !(t.flags & (ts.TypeFlags.Undefined | ts.TypeFlags.Null | ts.TypeFlags.Void)));
		return parts;
	}
	return [type];
}

function isUploadable(type) {
	const s = checker.typeToString(type);
	return /Uploadable|ReadStream|Blob|File\b|Buffer/.test(s);
}

function describeType(type, depth = 0) {
	const parts = stripNullish(type);
	if (parts.length === 0) return { kind: 'json', skeleton: null };
	if (parts.some((p) => p.flags & (ts.TypeFlags.Any | ts.TypeFlags.Unknown))) return { kind: 'json', skeleton: {} };
	if (parts.every((p) => p.flags & ts.TypeFlags.StringLiteral)) {
		return { kind: 'options', options: parts.map((p) => p.value), skeleton: parts[0].value };
	}
	if (parts.every((p) => p.flags & ts.TypeFlags.BooleanLike)) return { kind: 'boolean', skeleton: false };
	if (parts.every((p) => p.flags & (ts.TypeFlags.String | ts.TypeFlags.StringLiteral)))
		return { kind: 'string', skeleton: 'string' };
	if (parts.every((p) => p.flags & (ts.TypeFlags.Number | ts.TypeFlags.NumberLiteral)))
		return { kind: 'number', skeleton: 0 };
	if (parts.every((p) => p.flags & (ts.TypeFlags.String | ts.TypeFlags.Number | ts.TypeFlags.StringLiteral | ts.TypeFlags.NumberLiteral)))
		return { kind: 'string', skeleton: 'string' };
	if (parts.length === 1 && isUploadable(parts[0])) return { kind: 'file', skeleton: null };
	// T | T[] (repeatable query params) → treat as array of T
	const arrays = parts.filter((p) => checker.isArrayType(p));
	if (arrays.length === 1 && parts.length > 1) {
		const arr = describeType(arrays[0], depth);
		if (['stringArray', 'numberArray', 'multiOptions'].includes(arr.kind)) return arr;
	}
	if (parts.length === 1 && checker.isArrayType(parts[0])) {
		const elem = checker.getTypeArguments(parts[0])[0];
		const e = describeType(elem, depth + 1);
		if (e.kind === 'string') return { kind: 'stringArray', skeleton: ['string'] };
		if (e.kind === 'number') return { kind: 'numberArray', skeleton: [0] };
		if (e.kind === 'options') return { kind: 'multiOptions', options: e.options, skeleton: [e.options[0]] };
		return { kind: 'json', skeleton: depth > 3 ? [] : [e.skeleton] };
	}
	if (parts.length === 1 && parts[0].flags & ts.TypeFlags.Object) {
		return { kind: 'json', skeleton: objectSkeleton(parts[0], depth) };
	}
	// heterogeneous union → JSON (use first object-ish member for skeleton)
	const obj = parts.find((p) => p.flags & ts.TypeFlags.Object);
	return { kind: 'json', skeleton: obj ? describeType(obj, depth).skeleton : 'string' };
}

function objectSkeleton(type, depth) {
	if (depth > 3) return {};
	const out = {};
	const idx = type.getStringIndexType();
	for (const prop of checker.getPropertiesOfType(type)) {
		const decl = prop.valueDeclaration || (prop.declarations && prop.declarations[0]);
		const pt = decl ? checker.getTypeOfSymbolAtLocation(prop, decl) : checker.getTypeOfSymbol(prop);
		out[prop.getName()] = describeType(pt, depth + 1).skeleton;
	}
	if (idx && Object.keys(out).length === 0) out.key = describeType(idx, depth + 1).skeleton;
	return out;
}

function propsOfType(type) {
	const out = [];
	for (const prop of checker.getPropertiesOfType(type)) {
		const decl = prop.valueDeclaration || (prop.declarations && prop.declarations[0]);
		const pt = decl ? checker.getTypeOfSymbolAtLocation(prop, decl) : checker.getTypeOfSymbol(prop);
		const optional = !!(prop.flags & ts.SymbolFlags.Optional);
		const doc = cleanDoc(ts.displayPartsToString(prop.getDocumentationComment(checker)));
		out.push({ name: prop.getName(), type: pt, required: !optional, description: doc });
	}
	return out;
}

// ---------------------------------------------------------------- AST helpers
function walk(node, cb) {
	cb(node);
	ts.forEachChild(node, (c) => walk(c, cb));
}

function getProp(obj, name) {
	return obj.properties.find((p) => p.name && p.name.getText() === name);
}

function identifiersIn(node) {
	const ids = [];
	walk(node, (n) => {
		if (ts.isIdentifier(n)) ids.push(n.text);
	});
	return ids;
}

function requestPropRef(expr, destructured) {
	// request.foo  |  foo (destructured)  | foo?.toString()
	let found = null;
	walk(expr, (n) => {
		if (found) return;
		if (ts.isPropertyAccessExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'request') {
			found = n.name.text;
		} else if (ts.isElementAccessExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'request' && ts.isStringLiteral(n.argumentExpression)) {
			found = n.argumentExpression.text;
		} else if (ts.isIdentifier(n) && destructured[n.text]) {
			found = destructured[n.text];
		}
	});
	return found;
}

// ---------------------------------------------------------------- main extraction
const operations = [];
const warnings = [];

for (const resource of clientFiles) {
	const file = path.join(resourcesDir, resource, 'client/Client.ts');
	const sf = program.getSourceFile(file);
	const cls = sf.statements.find(ts.isClassDeclaration);
	const publicDocs = {};
	for (const m of cls.members) {
		if (ts.isMethodDeclaration(m) && !m.name.getText().startsWith('_')) {
			const sym = checker.getSymbolAtLocation(m.name);
			const doc = sym ? ts.displayPartsToString(sym.getDocumentationComment(checker)) : '';
			const deprecated = (ts.getJSDocTags(m) || []).some((t) => t.tagName.text === 'deprecated');
			publicDocs[m.name.getText()] = { doc, deprecated };
		}
	}

	for (const m of cls.members) {
		if (!ts.isMethodDeclaration(m) || !m.name.getText().startsWith('__')) continue;
		const opName = m.name.getText().slice(2);
		const reqParam = m.parameters.find((p) => p.name.getText() === 'request');
		const reqType = reqParam ? checker.getTypeAtLocation(reqParam) : null;
		const reqProps = reqType ? propsOfType(checker.getNonNullableType(reqType)) : [];
		const reqPropMap = Object.fromEntries(reqProps.map((p) => [p.name, p]));

		const destructured = {}; // local var -> request prop
		let restVar = null;
		const queryWire = []; // [wire, prop]
		const formParts = []; // {wire, prop, file}
		let fetcherObj = null;
		let constantBody = {};
		const commaQuery = new Set();

		walk(m.body, (n) => {
			if (ts.isVariableDeclaration(n) && ts.isObjectBindingPattern(n.name) && n.initializer && n.initializer.getText() === 'request') {
				for (const el of n.name.elements) {
					if (el.dotDotDotToken) restVar = el.name.getText();
					else destructured[el.name.getText()] = (el.propertyName || el.name).getText().replace(/^["']|["']$/g, '');
				}
			}
			if (ts.isVariableDeclaration(n) && n.name.getText() === '_queryParams' && n.initializer && ts.isObjectLiteralExpression(n.initializer)) {
				for (const p of n.initializer.properties) {
					const wire = p.name.getText().replace(/^["']|["']$/g, '');
					const ref = ts.isShorthandPropertyAssignment(p) ? destructured[p.name.getText()] || p.name.getText() : requestPropRef(p.initializer, destructured);
					queryWire.push([wire, ref]);
				}
			}
			if (ts.isCallExpression(n) && ts.isPropertyAccessExpression(n.expression) && n.expression.expression.getText() === '_body') {
				const meth = n.expression.name.text;
				if (meth === 'append' || meth === 'appendFile') {
					const wire = n.arguments[0].text;
					const ref = requestPropRef(n.arguments[1], destructured);
					formParts.push({ wire, prop: ref, file: meth === 'appendFile' });
				}
			}
			if (ts.isCallExpression(n) && n.expression.getText() === 'core.fetcher') fetcherObj = n.arguments[0];
			if (ts.isCallExpression(n) && ts.isPropertyAccessExpression(n.expression) && n.expression.name.text === 'add' && n.arguments.length === 3 && /style:\s*"comma"/.test(n.arguments[2].getText())) {
				commaQuery.add(n.arguments[0].text);
			}
		});

		if (!fetcherObj) {
			warnings.push(`${resource}.${opName}: no fetcher`);
			continue;
		}
		const method = getProp(fetcherObj, 'method').initializer.text;
		const urlCall = getProp(fetcherObj, 'url').initializer;
		const urlArg = urlCall.arguments[urlCall.arguments.length - 1];
		const pathParams = [];
		let urlPath;
		if (ts.isStringLiteral(urlArg) || ts.isNoSubstitutionTemplateLiteral(urlArg)) urlPath = urlArg.text;
		else if (ts.isTemplateExpression(urlArg)) {
			urlPath = urlArg.head.text;
			for (const span of urlArg.templateSpans) {
				const ref = requestPropRef(span.expression, destructured);
				pathParams.push(ref);
				urlPath += `{${ref}}` + span.literal.text;
			}
		} else warnings.push(`${resource}.${opName}: unknown url ${urlArg.getText()}`);
		urlPath = '/' + urlPath.replace(/^\//, '');

		const reqTypeProp = getProp(fetcherObj, 'requestType');
		const requestType = reqTypeProp ? reqTypeProp.initializer.text : null;
		const bodyProp = getProp(fetcherObj, 'body');

		const params = [];
		const used = new Set();
		const addParam = (location, wire, propName, extra = {}) => {
			const p = reqPropMap[propName];
			if (!p) {
				warnings.push(`${resource}.${opName}: unknown prop ${propName}`);
				return;
			}
			used.add(propName);
			const d = describeType(p.type);
			const param = {
				name: propName,
				wire,
				in: location,
				type: d.kind,
				required: location === 'path' ? true : p.required,
				description: p.description,
			};
			if (d.options) param.options = d.options;
			if (d.kind === 'json') param.example = d.skeleton;
			Object.assign(param, extra);
			params.push(param);
		};

		for (const pp of pathParams) addParam('path', pp, pp);
		for (const [wire, ref] of queryWire) if (ref) addParam('query', wire, ref, commaQuery.has(wire) ? { style: 'comma' } : {});

		let bodyMode = 'none';
		if (bodyProp) {
			const bodyText = bodyProp.initializer.getText();
			if (requestType === 'file') {
				bodyMode = 'multipart';
				for (const fp of formParts) addParam('form', fp.wire, fp.prop, fp.file ? { type: 'file' } : {});
			} else {
				bodyMode = requestType === 'form' ? 'form' : 'json';
				const mergeArg = ts.isCallExpression(bodyProp.initializer) ? bodyProp.initializer.arguments[0] : bodyProp.initializer;
				const argText = mergeArg.getText();
				if (argText === 'request' || (restVar && argText === restVar)) {
					for (const p of reqProps) if (!used.has(p.name)) addParam('body', p.name, p.name);
				} else if (ts.isObjectLiteralExpression(mergeArg)) {
					for (const p of mergeArg.properties) {
						if (ts.isSpreadAssignment(p) && p.expression.getText() === 'request') {
							for (const rp of reqProps) if (!used.has(rp.name)) addParam('body', rp.name, rp.name);
						} else if (ts.isPropertyAssignment(p)) {
							constantBody[p.name.getText().replace(/^["']|["']$/g, '')] = JSON.parse(p.initializer.getText().replace(/^'|'$/g, '"'));
						}
					}
				} else if (ts.isIdentifier(mergeArg) && destructured[mergeArg.text]) {
					// e.g. const { campaignId, body: _body } = request → raw body root
					const propName = destructured[mergeArg.text];
					const p = reqPropMap[propName];
					used.add(propName);
					const inner = stripNullish(p.type);
					const isPlainObject =
						inner.length === 1 && inner[0].flags & ts.TypeFlags.Object && !checker.isArrayType(inner[0]) && checker.getPropertiesOfType(inner[0]).length > 0;
					if (isPlainObject) {
						for (const bp of propsOfType(inner[0])) {
							const d = describeType(bp.type);
							const param = { name: bp.name, wire: bp.name, in: 'body', type: d.kind, required: bp.required, description: bp.description };
							if (d.options) param.options = d.options;
							if (d.kind === 'json') param.example = d.skeleton;
							params.push(param);
						}
					} else {
						const d = describeType(p.type);
						params.push({ name: propName, wire: propName, in: 'bodyRoot', type: 'json', required: p.required, description: p.description || 'Request body', example: d.skeleton });
					}
				} else if (bodyText === '{}') {
					// empty body
				} else {
					warnings.push(`${resource}.${opName}: unhandled body ${bodyText}`);
				}
			}
		}
		for (const p of reqProps) if (!used.has(p.name) && !params.find((x) => x.name === p.name)) warnings.push(`${resource}.${opName}: unused prop ${p.name}`);

		// return type
		const sig = checker.getSignatureFromDeclaration(m);
		const ret = checker.typeToString(checker.getReturnTypeOfSignature(sig));
		const binaryResponse = /BinaryResponse/.test(ret);

		const docInfo = publicDocs[opName] || { doc: '', deprecated: false };
		const hasLimit = params.find((p) => p.in === 'query' && p.wire === 'limit');
		const hasOffset = params.find((p) => p.in === 'query' && p.wire === 'offset');

		const op = {
			resource,
			operation: opName,
			name: humanize(opName),
			action: firstSentence(docInfo.doc, 120) || humanize(opName),
			description: cleanDoc(docInfo.doc),
			method,
			path: urlPath,
			bodyMode,
			params,
		};
		if (Object.keys(constantBody).length) op.constantBody = constantBody;
		if (binaryResponse) op.binaryResponse = true;
		if (docInfo.deprecated) op.deprecated = true;
		if (method === 'GET' && hasLimit && hasOffset && hasLimit.type === 'number' && hasOffset.type === 'number') op.paginated = true;
		operations.push(op);
	}
}

// Disambiguate duplicate display names inside a resource
const seen = {};
for (const op of operations) {
	const k = op.resource + '|' + op.name;
	seen[k] = (seen[k] || 0) + 1;
}
for (const op of operations) if (seen[op.resource + '|' + op.name] > 1) op.name += ` (${op.method} ${op.path})`;

const resources = clientFiles
	.filter((r) => operations.some((o) => o.resource === r))
	.map((r) => ({ value: r, name: RESOURCE_NAMES[r] || humanize(r) }));

const header = `// AUTO-GENERATED by scripts/generate-operations.js from @getbrevo/brevo v${sdkVersion}.\n// Do not edit by hand: re-run the generator instead.\n/* eslint-disable */\n\nimport type { BrevoOperation, BrevoResource } from './types';\n\n`;
const body =
	`export const SDK_VERSION = ${JSON.stringify(sdkVersion)};\n\n` +
	`export const resources: BrevoResource[] = ${JSON.stringify(resources, null, '\t')};\n\n` +
	`export const operations: BrevoOperation[] = ${JSON.stringify(operations, null, '\t')};\n`;
fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, header + body);

console.log(`Resources: ${resources.length}, operations: ${operations.length}`);
if (warnings.length) {
	console.log(`Warnings (${warnings.length}):`);
	for (const w of warnings) console.log('  - ' + w);
}

// ---------------------------------------------------------------- docs/OPERATIONS.md
const docLines = [
	'# Operations',
	'',
	`Auto-generated from \`@getbrevo/brevo\` v${sdkVersion}: **${operations.length} endpoints** across **${resources.length} resources**.`,
	'',
];
for (const r of [...resources].sort((a, b) => a.name.localeCompare(b.name))) {
	const ops = operations.filter((o) => o.resource === r.value).sort((a, b) => a.name.localeCompare(b.name));
	docLines.push(`## ${r.name}`, '', '| Operation | Method | Path |', '|---|---|---|');
	for (const o of ops) {
		docLines.push(`| ${o.name.replace(/\|/g, '\\|')}${o.deprecated ? ' *(deprecated)*' : ''} | \`${o.method}\` | \`${o.path.replace(/^\/\.\./, '')}\` |`);
	}
	docLines.push('');
}
const docsFile = path.resolve(__dirname, '../docs/OPERATIONS.md');
fs.mkdirSync(path.dirname(docsFile), { recursive: true });
fs.writeFileSync(docsFile, docLines.join('\n'));
